import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353;

    static long modExp(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    static long[] factorial;

    public static long nCr(int n, int r) {
        if (n < r) return 0;
        long numerator = factorial[n];
        long denominator = (factorial[n - r] * factorial[r]) % MOD;
        return (numerator * modExp(denominator, MOD - 2)) % MOD;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        int maxN = 200001;
        factorial = new long[maxN];
        factorial[0] = 1;
        for (int i = 1; i < maxN; i++) {
            factorial[i] = (factorial[i - 1] * i) % MOD;
        }
        String[] input = br.readLine().split(" ");
        int n = Integer.parseInt(input[0]);
        long k = Long.parseLong(input[1]);
        if (k >= n) {
            pw.println(0);
            pw.flush();
            return;
        }
        if (k == 0) {
            pw.println(factorial[n]);
            pw.flush();
            return;
        }
        if (k == n - 1) {
            pw.println(2L * n);
            pw.flush();
            return;
        }
        int filledColumns = (int)(n - k);
        long chooseFilledCols = nCr(n, filledColumns);
        long answer = 0;
        for (int emptyCols = 0; emptyCols <= filledColumns; emptyCols++) {
            long choose = nCr(filledColumns, emptyCols);
            long fillWays = modExp(filledColumns - emptyCols, n);
            long val = (choose * fillWays) % MOD;
            if (emptyCols % 2 == 1) {
                val = (MOD - val) % MOD;
            }
            answer = (answer + val) % MOD;
        }
        answer = (answer * chooseFilledCols) % MOD;
        answer = (answer * 2) % MOD;
        pw.println(answer);
        pw.flush();
    }
}
